import csv
import io
import json

FIELDS = ("id", "name")


def _normalize(rows):
    """Yield new dicts holding only id and name as strings; inputs are not mutated."""
    for row in rows:
        yield {key: "" if row.get(key) is None else str(row[key]) for key in FIELDS}


def _to_csv(clean):
    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(FIELDS)
    for row in clean:
        writer.writerow([row[key] for key in FIELDS])
    return buffer.getvalue()


def _to_json(clean):
    return json.dumps(list(clean), ensure_ascii=False, separators=(",", ":"))


_SERIALIZERS = {"csv": _to_csv, "json": _to_json}


def export_rows(rows, format):
    try:
        serialize = _SERIALIZERS[format]
    except (KeyError, TypeError):
        raise ValueError("unsupported format") from None
    return serialize(_normalize(rows))
